package com.dy.artisan3d.data.model.artisan.aboutimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializable@Serializabledata class ArtisanAboutDto(    val id: Int? = null,    @SerialName("about_image") val aboutImage: String? = null,    @SerialName("birth_date") val birthDate: String? = null,    val translations: Map<String, AboutTranslationDto>? = null,    val educations: List<EducationDto>? = null,    val publications: List<PublicationDto>? = null)